set -eu; printf '%s\n' 'POCKETBOOT_A5U_DRM_INVENTORY_V1'; printf 'cmdline\t/proc/cmdline\t'; cat /proc/cmdline; for pb_p in /sys/kernel/debug/dri/*/name; do [ -r "$pb_p" ] || continue; pb_b=${pb_p%/name}; pb_b=${pb_b##*/}; case "$pb_b" in ''|*[!0-9]*) continue;; esac; printf 'dri-name\t%s\t' "$pb_p"; cat "$pb_p"; done; for pb_p in /sys/class/drm/card[0-9]*; do [ -d "$pb_p" ] || continue; pb_b=${pb_p##*/}; case "$pb_b" in *-*) continue;; esac; pb_d=; [ ! -L "$pb_p/device/driver" ] || pb_d=$(readlink "$pb_p/device/driver" || true); printf 'card-driver\t%s\t%s\n' "$pb_p" "${pb_d##*/}"; done; for pb_p in /sys/class/drm/card[0-9]*-DSI-*; do [ -d "$pb_p" ] || continue; for pb_f in status enabled; do [ -r "$pb_p/$pb_f" ] || continue; pb_v=$(cat "$pb_p/$pb_f"); printf 'connector-%s\t%s\t%s\n' "$pb_f" "$pb_p" "$pb_v"; done; [ ! -r "$pb_p/modes" ] || while IFS= read -r pb_v; do printf 'connector-mode\t%s\t%s\n' "$pb_p" "$pb_v"; done < "$pb_p/modes"; done
for pb_p in /sys/kernel/debug/dri/*/state; do test -r "$pb_p" || continue; printf "state=%s\n" "$pb_p"; cat "$pb_p"; done
